preset.frame_eqs_eel:
wave_a = 0;



//Thanks to Zylot for rainbow generator
counter1 = if(equal(counter2,1),if(equal(counter1,1),0,counter1+.2),1);
counter2 = if(equal(counter1,1),if(equal(counter2,1),0,counter2+.2),1);
cdelay1 = if(equal(cdelay2,1),1,if(equal(colorcounter%2,1),if(equal(counter1,1),2 ,0), if(equal(counter2,1),2,0)));
cdelay2 = if(equal(cdelay1,2),1,0);
colorcounter = if(above(colorcounter,7),0,if(equal(cdelay1,1),colorcounter+1,colorcounter));
ib_r = .5*if(equal(colorcounter,1),1, if(equal(colorcounter,2),1, if(equal(colorcounter,3),1, if(equal(colorcounter,4),sin(counter2+2.1), if(equal(colorcounter,5),0, if(equal(colorcounter,6),0,sin(counter1)))))));
ib_g = .5*if(equal(colorcounter,1),0, if(equal(colorcounter,2),sin(counter2*.5), if(equal(colorcounter,3),sin((counter1+1.75)*.4), if(equal(colorcounter,4),1, if(equal(colorcounter,5),1, if(equal(colorcounter,6),sin(counter2+2),0))))));
ib_b = if(equal(colorcounter,1),sin(counter1+2.1), if(equal(colorcounter,2),0, if(equal(colorcounter,3),0, if(equal(colorcounter,4),0, if(equal(colorcounter,5),sin(counter1), if(equal(colorcounter,6),1,1))))));



ob_r=ib_r-0.5;
ob_g=ib_g-0.5;
ob_b=ib_b-0.5;
q1=ib_r;
q2=ib_g;
q3=ib_b;



decay = 0.9999;


//echo_orient=((bass_att+mid_att+treb_att)/3)*3;
//solarize=above(0.5,bass);
//darken=above(0.4,treb);

musictime=musictime+(mid*mid*mid)*0.02;

xpos=sin(musictime*0.6)*0.6;
ypos=sin(musictime*0.4)*0.6;
q4=xpos;
q5=ypos;



//beatdetect
volume = 0.3*(bass+mid+att);
beatrate = if(equal(beatrate,0),1,if(below(volume,0.01),1,beatrate));
lastbeat = if(equal(lastbeat,0),time,lastbeat);
meanbass_att = 0.1*(meanbass_att*9 + bass_att);
beat = if(above(volume,0.8),if(below(peakbass_att - bass_att, 0.05*peakbass_att),if(above(time - lastbeat,0.1+0.5*(beatrate-0.1)),1,0),0),0);
beatrate = max(if(beat,if(below(time-lastbeat,2*beatrate),0.5*(beatrate + time - lastbeat),beatrate),beatrate),0.1);
peakbass_att = if(equal(beat,0),if(above(time - lastbeat,2*beatrate),peakbass_att*0.95,peakbass_att*0.995),bass_att);
lastbeat = if(beat,time,lastbeat);
peakbass_att = max(if(beat,bass_att,peakbass_att),1.1*meanbass_att);

mybeat=if(beat,mybeat+1,mybeat);
mybeat=if(above(mybeat,3),0,mybeat);
echo_orient=mybeat;

